argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R70-GPT-PLANNER-20261014-GPT6'
$sha='14c085251a63411d5c50349dac0e124a82ef3766'
if(@(& git.exe -C $root status --porcelain=v1 --untracked-files=no).Count -ne 0){throw 'TRACKED_DIRTY'}
& git.exe -C $root fetch --quiet --no-tags origin agent/r70-gated-gpt-planner-staging-20261014
if($LASTEXITCODE -ne 0){throw 'FETCH_FAILED'}
& git.exe -C $root checkout --quiet --detach $sha
if($LASTEXITCODE -ne 0){throw 'CHECKOUT_FAILED'}
if(([string](& git.exe -C $root rev-parse HEAD)).Trim() -ne $sha){throw 'SHA_MISMATCH'}
$tests=@('autonomy-r45.test.js','autonomy-r45-brain.test.js','autonomy-r45-git-gate.test.js','autonomy-r45-lock.test.js','autonomy-r45-review.test.js','autonomy-r45-launcher.test.js','autonomy-r57-gpt-git.test.js','autonomy-r57-successor.test.js','operator-lifecycle-r40.test.js','projects-live-control-plane-r41.test.js','live-control-plane-cutover-r42.test.js','autonomous-send-gate-r50.test.js','existing-tab-session-r55.test.js','existing-tab-session-r56-cdp.test.js','r56-worker-sticky.test.js','r62-r42-sticky-release-gate.test.js','r63-r42-staged-activation.test.js','r64-idle-health-and-dryrun.test.js','r65-global-canary-cap.test.js','r68-live-chat-observability.test.js','r68-live-viewer.test.js','r69-viewer-bootstrap.test.js','r70-stage-gpt-planner.test.js','r70-idle-health-policy.test.js')
$log=Join-Path $root 'R70_FULL_FAIL_CLOSED_VERIFICATION.txt'
Push-Location (Join-Path $root 'app')
try {
 & node.exe --check server.js
 $syntax=$LASTEXITCODE
 & node.exe --test @tests 2>&1 |Out-File -LiteralPath $log -Encoding UTF8
 $rc=$LASTEXITCODE
}finally{Pop-Location}
Write-Output ('SOURCE_SHA='+$sha)
Write-Output ('SOURCE_SYNTAX_EXIT='+$syntax)
Write-Output ('NODE_EXIT='+$rc)
Write-Output ('TEST_FILES='+$tests.Count)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 22|ForEach-Object{Write-Output $_.Line}
Write-Output ('PLAN_DISPATCH_ALLOWED='+((Get-Content (Join-Path $root 'app\data\r70-qa-verified-wave-plan.json') -Raw|ConvertFrom-Json).allowDispatch))
Write-Output ('PRODUCTION_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0 -or $syntax -ne 0){throw 'R70_NEGATIVE_SUITE_NOT_GREEN'}
